function freqTable(arr){ var m={}; arr.forEach(function(v){ var k=String(v); m[k]=(m[k]||0)+1; }); var keys=Object.keys(m).map(Number).sort(function(a,b){return a-b;}); return keys.map(function(k){ return {value:k, count:m[String(k)], pct:m[String(k)]/arr.length*100}; }); }
function histogram(arr, bins){ if(bins<1) bins=1; var min=Math.min.apply(null,arr), max=Math.max.apply(null,arr); if(min===max) return [{bin:min, count:arr.length}]; var w=(max-min)/bins; var counts=new Array(bins).fill(0); arr.forEach(function(v){ var idx=Math.min(bins-1, Math.floor((v-min)/w)); counts[idx]++; }); var out=[]; for(var i=0;i<bins;i++){ out.push({binLo:min+i*w, binHi:min+(i+1)*w, count:counts[i]}); } return out; }
var EXPORTS = { freqTable:freqTable, histogram:histogram };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.FrequencyForgePure = EXPORTS; }
